void transferMoney(long fromId, long toId, BigDecimal amount) throws SQLException {
  try (Connection c = ds.getConnection()) {
    c.setAutoCommit(false);
    try { updateBalance(c, fromId, amount.negate()); updateBalance(c, toId, amount); c.commit(); }
    catch (SQLException e) { c.rollback(); }
    finally { c.setAutoCommit(true); }
  }
}

